def _json_groups_find_all(
    groups: tuple[JsonSearchIndexGroup, ...], value: Any
) -> tuple[int, ...]:
    """Merge every hit of ``value`` across one pointer's hit groups.

    Shared core of :meth:`JsonSearchIndex.find` and
    :meth:`JsonMultiIndex.find`; JSON kind-separated equality with
    cross-kind numeric equality for ints/floats, merged in strictly
    ascending order. Range clipping is the caller's job.
    """
    by_kind = {group.kind: group for group in groups}
    streams: list[tuple[int, ...]] = []

    def add_bucket(kind: int, key: bytes) -> None:
        group = by_kind.get(kind)
        if group is None:
            return
        for bucket in group.buckets:
            if bucket.key == key:
                streams.append(bucket.hits)
                return

    if isinstance(value, bool):
        add_bucket(_JSON_TAG_TRUE if value else _JSON_TAG_FALSE, b"")
    elif value is None:
        add_bucket(_JSON_TAG_NULL, b"")
    elif isinstance(value, str):
        add_bucket(_JSON_TAG_STRING, value.encode("utf-8"))
    elif isinstance(value, int):
        add_bucket(_JSON_TAG_INTEGER, str(value).encode("ascii"))
        group = by_kind.get(_JSON_TAG_FLOAT)
        if group is not None:
            # Python compares an int and a float by exact rational value
            # without rounding the int, so big integers never spuriously
            # match a nearby float; compare against the decoded int query
            # directly rather than converting anything to float first.
            for bucket in group.buckets:
                if _decode_json_index_numeric(_JSON_TAG_FLOAT, bucket.key) == value:
                    streams.append(bucket.hits)
    else:
        # float (finiteness was checked above): numbers match across the
        # integer and float kinds by exact numeric value.
        group = by_kind.get(_JSON_TAG_FLOAT)
        if group is not None:
            for bucket in group.buckets:
                if _decode_json_index_numeric(_JSON_TAG_FLOAT, bucket.key) == value:
                    streams.append(bucket.hits)
        group = by_kind.get(_JSON_TAG_INTEGER)
        if group is not None:
            for bucket in group.buckets:
                if _decode_json_index_numeric(
                    _JSON_TAG_INTEGER, bucket.key
                ) == value:
                    streams.append(bucket.hits)
    merged = heapq.merge(*streams) if streams else ()
    return tuple(merged)


def _json_groups_find_range(
    groups: tuple[JsonSearchIndexGroup, ...], operator: str, threshold: Any
) -> tuple[int, ...]:
    """Merge every hit of a numeric comparison over one pointer's groups.

    Shared core of the ``lt`` / ``le`` / ``gt`` / ``ge`` leaves of
    :meth:`JsonMultiIndex.find_where`. Only the integer and float kinds
    take part — strings, booleans and null never satisfy a numeric
    comparison — and ints and floats compare by exact numeric value
    across both kinds: Python compares an int and a float by exact
    rational value without rounding the int, so big integers never
    spuriously compare equal to a nearby float threshold, and negative
    zero equals positive zero. The matching buckets' hits merge in
    strictly ascending order; range clipping is the caller's job.
    """
    if operator == "lt":

        def matches(number: Any) -> bool:
            return number < threshold

    elif operator == "le":

        def matches(number: Any) -> bool:
            return number <= threshold

    elif operator == "gt":

        def matches(number: Any) -> bool:
            return number > threshold

    else:  # "ge"

        def matches(number: Any) -> bool:
            return number >= threshold

    streams: list[tuple[int, ...]] = []
    for group in groups:
        if group.kind not in (_JSON_TAG_INTEGER, _JSON_TAG_FLOAT):
            continue
        for bucket in group.buckets:
            number = _decode_json_index_numeric(group.kind, bucket.key)
            if matches(number):
                streams.append(bucket.hits)
    merged = heapq.merge(*streams) if streams else ()
    return tuple(merged)


def _intersect_ascending_tuples(
    left: tuple[int, ...], right: tuple[int, ...]
) -> tuple[int, ...]:
    """Intersect two strictly ascending, duplicate-free index tuples.

    Shared core of :meth:`JsonMultiIndex.find_all`; the merge walk keeps
    the result strictly ascending and duplicate free.
    """
    i = j = 0
    shared: list[int] = []
    while i < len(left) and j < len(right):
        if left[i] == right[j]:
            shared.append(left[i])
            i += 1
            j += 1
        elif left[i] < right[j]:
            i += 1
        else:
            j += 1
    return tuple(shared)


def _union_ascending_tuples(
    streams: tuple[tuple[int, ...], ...],
) -> tuple[int, ...]:
    """Union strictly ascending, duplicate-free index tuples.

    Shared core of the ``or`` combination of
    :meth:`JsonMultiIndex.find_where`; the merged walk keeps the result
    strictly ascending and drops duplicates from overlapping inputs.
    """
    merged = heapq.merge(*streams) if streams else ()
    result: list[int] = []
    for index in merged:
        if not result or result[-1] != index:
            result.append(index)
    return tuple(result)


def _complement_ascending_tuple(
    hits: tuple[int, ...], start: int, stop: int
